    TEST(cellToBoundary_failed) {
        H3Index h = 0x87dc6d364ffffffL;
        H3_SET_BASE_CELL(h, NUM_BASE_CELLS + 1);
        CellBoundary gb;
        t_assert(H3_EXPORT(cellToBoundary(h, &gb) == E_CELL_INVALID),
                 "cellToBoundary fails on invalid index");
